-- Run once in a new Supabase project. Demo data is intentionally separate.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, name text not null,email text not null,role text not null check(role in ('super_admin','admin','leader','employee')), team_id text not null default 'Creative', active boolean not null default true,created_at timestamptz not null default now());
alter table public.profiles enable row level security;
create function public.current_role() returns text language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid() and active$$;
create function public.current_team() returns text language sql stable security definer set search_path=public as $$select team_id from profiles where id=auth.uid() and active$$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce(current_role() in ('admin','super_admin'),false)$$;
create policy profiles_read on profiles for select to authenticated using (id=auth.uid() or is_admin() or (current_role()='leader' and team_id=current_team()));
-- Profile writes are only performed by the authorized server function or employee sync trigger.
create table public.employees (id uuid primary key default gen_random_uuid(), name text not null, status text not null default 'Active', description text, department text, email text, role text, assignee uuid references public.profiles(id), owner_id uuid references public.profiles(id) default auth.uid(),team_id text, due date, priority text, hours numeric not null default 0 check(hours>=0), amount numeric not null default 0 check(amount>=0), author text, storage_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
