-- Employee status updates immediately revoke data access for inactive profiles.
create function public.sync_employee_profile() returns trigger language plpgsql security definer set search_path=public as $$begin
if not is_admin() and current_user <> 'postgres' and auth.role() <> 'service_role' then raise exception 'Admin access required'; end if;
if current_role()='admin' and (new.role in ('admin','super_admin') or old.role in ('admin','super_admin')) then raise exception 'Only owner may manage administrators'; end if;
update profiles set name=new.name,email=new.email,role=coalesce(new.role,'employee'),team_id=coalesce(new.department,'Creative'),active=new.status not in ('Inactive','Exited') where id=new.id;
return new;end$$;
create trigger sync_employee after update on employees for each row execute function sync_employee_profile();
-- Prevent employees changing task responsibility, dates or priority through direct API calls.
create function public.guard_task_update() returns trigger language plpgsql set search_path=public as $$begin
if current_role()='employee' and (new.name is distinct from old.name or new.assignee is distinct from old.assignee or new.owner_id is distinct from old.owner_id or new.team_id is distinct from old.team_id or new.project_id is distinct from old.project_id or new.client_id is distinct from old.client_id or new.due is distinct from old.due or new.priority is distinct from old.priority or new.hours is distinct from old.hours or new.amount is distinct from old.amount) then raise exception 'Employees can only update task status and description';end if;return new;end$$;
create trigger guard_task before update on tasks for each row execute function guard_task_update();
-- Database audit runs even when changes are made outside the UI.
create function public.audit_record() returns trigger language plpgsql security definer set search_path=public as $$begin
insert into activity_logs(name,status,owner_id,description) values(coalesce(auth.uid()::text,'server')||' '||TG_OP||' '||TG_TABLE_NAME,'Recorded',auth.uid(),jsonb_build_object('old',case when TG_OP='INSERT' then null else to_jsonb(old) end,'new',case when TG_OP='DELETE' then null else to_jsonb(new) end)::text);return coalesce(new,old);end$$;
create trigger audit_tasks after insert or update or delete on tasks for each row execute function audit_record();
create trigger audit_projects after insert or update or delete on projects for each row execute function audit_record();
create trigger audit_employees after insert or update or delete on employees for each row execute function audit_record();
create trigger audit_payroll after insert or update or delete on payroll for each row execute function audit_record();
create trigger audit_clients after insert or update or delete on clients for each row execute function audit_record();
create trigger audit_expenses after insert or update or delete on expenses for each row execute function audit_record();
create trigger audit_invoices after insert or update or delete on invoices for each row execute function audit_record();
create function public.task_notification() returns trigger language plpgsql security definer set search_path=public as $$begin
if TG_OP='INSERT' or new.status is distinct from old.status or new.assignee is distinct from old.assignee then
insert into notifications(name,status,assignee,team_id,description) values(new.name||' · '||new.status,'Unread',new.assignee,new.team_id,'Task updated in your workspace.');
end if; return new; end$$;
create trigger task_notifications after insert or update on tasks for each row execute function task_notification();
insert into storage.buckets(id,name,public) values('agency-files','agency-files',false);
create policy agency_storage_select on storage.objects for select to authenticated using(bucket_id='agency-files' and (is_admin() or (current_role() is not null and (storage.foldername(name))[1]=auth.uid()::text)));
create policy agency_storage_insert on storage.objects for insert to authenticated with check(bucket_id='agency-files' and current_role() is not null and (storage.foldername(name))[1]=auth.uid()::text);
create policy agency_storage_delete on storage.objects for delete to authenticated using(bucket_id='agency-files' and (is_admin() or (current_role() is not null and (storage.foldername(name))[1]=auth.uid()::text)));
-- Enable realtime for operational changes. Other tables refresh after a mutation.
alter publication supabase_realtime add table public.tasks,public.notifications,public.projects,public.attendance;

alter table public.employees add column project_id uuid references public.projects(id) on delete set null, add column client_id uuid references public.clients(id) on delete set null;
alter table public.clients add column project_id uuid references public.projects(id) on delete set null,add column client_id uuid references public.clients(id) on delete set null;
alter table public.projects add column project_id uuid references public.projects(id) on delete set null;
create policy files_own_delete on files for delete to authenticated using(current_role() is not null and owner_id=auth.uid());

create policy project_employee_membership on projects for select to authenticated using(current_role()='employee' and exists(select 1 from tasks t where t.project_id=projects.id and t.assignee=auth.uid()));
create policy approvals_leader_insert on approvals for insert to authenticated with check(current_role()='leader' and team_id=current_team() and owner_id=auth.uid());

create function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create trigger touch_employees before update on public.employees for each row execute function touch_updated_at();
create trigger touch_clients before update on public.clients for each row execute function touch_updated_at();
